import Ajv from "ajv"

/* ---------------------------------------------
   Ajv Initialization (Single Instance)
   AJV 初期化
--------------------------------------------- */

const ajv = new Ajv({
  schemaId: "auto",
  allErrors: true,
  verbose: true
})

ajv.addMetaSchema(require("ajv/lib/refs/json-schema-draft-06.json"))
ajv.addMetaSchema(require("ajv/lib/refs/json-schema-draft-04.json"))

/* ---------------------------------------------
   Default Error Handler
   デフォルトエラーハンドラ
--------------------------------------------- */

export const defaultValidationErrorHandler = (message, violations) => {
  const msg = JSON.stringify(
    {
      type: "Typewriter JSON Schema Validation Error",
      description:
        `You made an analytics call (${message.event}) using Typewriter that doesn't match the Tracking Plan spec.`,
      errors: violations
    },
    undefined,
    2
  )

  console.warn(msg)
}

let onViolation = defaultValidationErrorHandler

let analytics = () => window.analytics

/* ---------------------------------------------
   Runtime Options
--------------------------------------------- */

export function setTypewriterOptions(options) {

  analytics = options.analytics
    ? () => options.analytics || window.analytics
    : analytics

  onViolation = options.onViolation || onViolation
}

/* ---------------------------------------------
   Validation Helper
--------------------------------------------- */

function validate(validator, message) {
  const valid = validator(message)

  if (!valid && validator.errors) {
    onViolation(message, validator.errors)
  }
}

/* ---------------------------------------------
   Typewriter Context
--------------------------------------------- */

function withTypewriterContext(message = {}) {
  return {
    ...message,
    context: {
      ...(message.context || {}),
      typewriter: {
        language: "javascript",
        version: "7.0.1"
      }
    }
  }
}

/* ---------------------------------------------
   Schema Definitions
--------------------------------------------- */

const docsSearchedSchema = {
  type: "object",
  required: ["properties"],
  properties: {
    properties: {
      type: "object",
      required: ["query"],
      properties: {
        query: { type: "string" }
      }
    }
  }
}

/* Compile Once */
const validateDocsSearched = ajv.compile(docsSearchedSchema)

/* ---------------------------------------------
   Event Functions
--------------------------------------------- */

export function docsSearched(props, options, callback) {

  const message = {
    event: "Docs Searched",
    properties: props || {},
    options
  }

  validate(validateDocsSearched, message)

  const a = analytics()

  if (a) {
    a.track(
      "Docs Searched",
      props || {},
      withTypewriterContext(options),
      callback
    )
  }
}
